.darma-loader-darma-b15-rotisserie-spin { --accent: var(--loader-color, #ea580c); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 118px); height: calc(var(--loader-size, 118px) * .7); position: relative; }
.darma-loader-darma-b15-rotisserie-spin .darma-loader-darma-b15-rotisserie-spin__spit { position: absolute; left: 2%; right: 2%; top: 42%; height: 4%; border-radius: 2px; background: linear-gradient(#e2e8f0, #94a3b8); }
.darma-loader-darma-b15-rotisserie-spin i { position: absolute; top: 28%; width: 21%; height: 32%; border-radius: 36%; background: linear-gradient(var(--accent-2), var(--accent)); animation: darma-loader-darma-b15-rotisserie-spin-roti-turn calc(var(--loader-speed, 1s) * 1.6) linear infinite; }
.darma-loader-darma-b15-rotisserie-spin i:nth-of-type(1) { left: 11%; }
.darma-loader-darma-b15-rotisserie-spin i:nth-of-type(2) { left: 39%; animation-delay: calc(var(--loader-speed, 1s) * -.53); }
.darma-loader-darma-b15-rotisserie-spin i:nth-of-type(3) { left: 67%; animation-delay: calc(var(--loader-speed, 1s) * -1.06); }
.darma-loader-darma-b15-rotisserie-spin .darma-loader-darma-b15-rotisserie-spin__flame { position: absolute; left: 12%; right: 12%; bottom: 5%; height: 17%; border-radius: 50% 50% 36% 36%; background: linear-gradient(#fde68a, var(--accent)); animation: darma-loader-darma-b15-rotisserie-spin-roti-fire calc(var(--loader-speed, 1s) * .55) ease-in-out infinite alternate; }
@keyframes darma-loader-darma-b15-rotisserie-spin-roti-turn { 0% { transform: rotate(0deg) scaleX(1); } 50% { transform: rotate(180deg) scaleX(.62); } 100% { transform: rotate(360deg) scaleX(1); } }
@keyframes darma-loader-darma-b15-rotisserie-spin-roti-fire { from { transform: scaleY(.7); opacity: .6; } to { transform: scaleY(1.15); opacity: 1; } }

